30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "telephone")
50	    @NotEmpty
51	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
52	    private String telephone;
53	
54	    @Column(name = "email")
55	    private String email;
56	
57	    @Column(name = "postcode")
58	    private String postcode;
59	
60	    @Column(name = "registration_date", columnDefinition = "DATE")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date", columnDefinition = "DATE")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "possible_duplicate")
76	    private Boolean possibleDuplicate;
77	
78	    @Column(name = "possible_duplicate_of")
79	    private Integer possibleDuplicateOf;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    /**
109	     * The stored E.164 {@code telephone} formatted for humans (e.g. {@code '+61 412 345 678'} for the
110	     * stored {@code '+61412345678'}); the raw {@code telephone} stays in E.164 form. Derived from the
111	     * owner's own {@code telephone}; see {@link TelephoneFormatter#toDisplay(String)}.
112	     */
113	    @Transient
114	    public String getTelephoneDisplay() {
115	        return TelephoneFormatter.toDisplay(this.telephone);
116	    }
117	
118	    public String getEmail() {
119	        return this.email;
120	    }
121	
122	    public void setEmail(String email) {
123	        this.email = email;
124	    }
125	
126	    public String getPostcode() {
127	        return this.postcode;
128	    }
129	
130	    public void setPostcode(String postcode) {
131	        this.postcode = postcode;
132	    }
133	
134	    public LocalDate getRegistrationDate() {
135	        return this.registrationDate;
136	    }
137	
138	    public void setRegistrationDate(LocalDate registrationDate) {
139	        this.registrationDate = registrationDate;
140	    }
141	
142	    public LocalDate getBirthDate() {
143	        return this.birthDate;
144	    }
145	
146	    public void setBirthDate(LocalDate birthDate) {
147	        this.birthDate = birthDate;
148	    }
149	
150	    public String getCustomerCode() {
151	        return this.customerCode;
152	    }
153	
154	    public void setCustomerCode(String customerCode) {
155	        this.customerCode = customerCode;
156	    }
157	
158	    public String getHouseholdId() {
159	        return this.householdId;
160	    }
161	
162	    public void setHouseholdId(String householdId) {
163	        this.householdId = householdId;
164	    }
165	
166	    public Integer getNamesakeCount() {
167	        return this.namesakeCount;
168	    }
169	
170	    public void setNamesakeCount(Integer namesakeCount) {
171	        this.namesakeCount = namesakeCount;
172	    }
173	
174	    /**
175	     * Whether this owner was flagged a possible (soft) duplicate at creation time: it was not a
176	     * hard duplicate, but shared an existing owner's last name and postcode while carrying a
177	     * different telephone. {@code false} (or {@code null} for owners created before the check) when
178	     * no such match was found.
179	     */
180	    public Boolean getPossibleDuplicate() {
181	        return this.possibleDuplicate;
182	    }
183	
184	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
185	        this.possibleDuplicate = possibleDuplicate;
186	    }
187	
188	    /**
189	     * The id of the existing owner this one was flagged a possible duplicate of, or {@code null}
190	     * when {@code possibleDuplicate} is not set.
191	     */
192	    public Integer getPossibleDuplicateOf() {
193	        return this.possibleDuplicateOf;
194	    }
195	
196	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
197	        this.possibleDuplicateOf = possibleDuplicateOf;
198	    }
199	
200	    /**
201	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
202	     */
203	    @Transient
204	    public String getDisplayName() {
205	        return this.getLastName() + ", " + this.getFirstName();
206	    }
207	
208	    /**
209	     * The owner's initials: the upper-cased first letters of the first and last name,
210	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
211	     */
212	    @Transient
213	    public String getInitials() {
214	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
215	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
216	    }
217	
218	    /**
219	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
220	     * the last two digits of the registration date year (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived
221	     * from the owner's own fields; {@code null} until both the customer code and registration date
222	     * are set.
223	     */
224	    @Transient
225	    public String getMembershipNumber() {
226	        if (this.customerCode == null || this.registrationDate == null) {
227	            return null;
228	        }
229	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
230	    }
231	
232	    /**
233	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
234	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
235	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
236	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
237	     */
238	    @Transient
239	    public Integer getCheckDigit() {
240	        if (this.customerCode == null) {
241	            return null;
242	        }
243	        int sum = 0;
244	        boolean dbl = true;
245	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
246	            char c = this.customerCode.charAt(i);
247	            if (c < '0' || c > '9') {
248	                continue;
249	            }
250	            int d = c - '0';
251	            if (dbl) {
252	                d *= 2;
253	                if (d > 9) {
254	                    d -= 9;
255	                }
256	            }
257	            sum += d;
258	            dbl = !dbl;
259	        }
260	        return (10 - (sum % 10)) % 10;
261	    }
262	
263	    /**
264	     * The owner's numeric membership level, from 1 to 4. It starts at 1, gains 1 when the owner has
265	     * an email address, gains 1 when the owner is unique (namesakeCount is 0), and is capped at 3 by
266	     * these pre-tenure factors. Level 4 is reserved for tenure: it is reached only when the owner's
267	     * tenure exceeds 365 days, measured from {@code registrationDate} to today. Because a newly
268	     * created owner has zero tenure, a new owner never exceeds level 3. The inputs are the owner's
269	     * own fields.
270	     */
271	    @Transient
272	    public Integer getMembershipLevel() {
273	        int level = 1;
274	        boolean hasEmail = this.email != null && !this.email.isBlank();
275	        if (hasEmail) {
276	            level++;
277	        }
278	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
279	        if (unique) {
280	            level++;
281	        }
282	        level = Math.min(level, 3);
283	        boolean tenured = this.registrationDate != null
284	            && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365;
285	        if (tenured) {
286	            level = 4;
287	        }
288	        return level;
289	    }
290	
291	    /**
292	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
293	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
294	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
295	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
296	     */
297	    @Transient
298	    public String getLocality() {
299	        if (this.customerCode == null) {
300	            return "UNKNOWN";
301	        }
302	        int dash = this.customerCode.indexOf('-');
303	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
304	    }
305	
306	    /**
307	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
308	     * formatted {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. The
309	     * telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
310	     * owner has none), and the household id the stored shared identifier (empty when the owner is
311	     * not part of a shared household). Two owners are duplicates only when their whole identity keys
312	     * are equal; because the telephone is part of the key, two members of the same household with
313	     * different telephones have different identity keys.
314	     */
315	    @Transient
316	    public String getIdentityKey() {
317	        String telephonePart = this.telephone == null ? "" : this.telephone;
318	        String emailPart = this.email == null ? "" : this.email;
319	        String householdPart = this.householdId == null ? "" : this.householdId;
320	        return telephonePart + "|" + emailPart + "|" + householdPart;
321	    }
322	
323	    /**
324	     * The owner's preferred contact channel, derived from the owner's own fields:
325	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
326	     */
327	    @Transient
328	    public String getContactPreference() {
329	        boolean hasEmail = this.email != null && !this.email.isBlank();
330	        return hasEmail ? "EMAIL" : "PHONE";
331	    }
332	
333	    /**
334	     * The owner's age band, derived from the owner's own fields: the whole number of years from
335	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
336	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
337	     * as of the registration date rather than today, so the band is stable over time. {@code null}
338	     * when the owner has no birth date (or no registration date to measure against).
339	     */
340	    @Transient
341	    public String getAgeBand() {
342	        if (this.birthDate == null || this.registrationDate == null) {
343	            return null;
344	        }
345	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
346	        if (age < 18) {
347	            return "MINOR";
348	        }
349	        if (age < 65) {
350	            return "ADULT";
351	        }
352	        return "SENIOR";
353	    }
354	
355	    protected Set<Pet> getPetsInternal() {
356	        if (this.pets == null) {
357	            this.pets = new HashSet<>();
358	        }
359	        return this.pets;
360	    }
361	
362	    protected void setPetsInternal(Set<Pet> pets) {
363	        this.pets = pets;
364	    }
365	
366	    public List<Pet> getPets() {
367	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
368	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
369	        return Collections.unmodifiableList(sortedPets);
370	    }
371	
372	    public void setPets(List<Pet> pets) {
373	        this.pets = new HashSet<>(pets);
374	    }
375	
376	    public void addPet(Pet pet) {
377	        getPetsInternal().add(pet);
378	        pet.setOwner(this);
379	    }
380	
381	    /**
382	     * Return the Pet with the given name, or null if none found for this Owner.
383	     *
384	     * @param name to test
385	     * @return true if pet name is already in use
386	     */
387	    public Pet getPet(String name) {
388	        return getPet(name, false);
389	    }
390	
391	    /**
392	     * Return the Pet with the given name, or null if none found for this Owner.
393	     *
394	     * @param name to test
395	     * @return true if pet name is already in use
396	     */
397	    public Pet getPet(String name, boolean ignoreNew) {
398	        name = name.toLowerCase();
399	        for (Pet pet : getPetsInternal()) {
400	            if (!ignoreNew || !pet.isNew()) {
401	                String compName = pet.getName();
402	                compName = compName.toLowerCase();
403	                if (compName.equals(name)) {
404	                    return pet;
405	                }
406	            }
407	        }
408	        return null;
409	    }
410	
411	    public Pet getPet(Integer petId) {
412	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
413	    }
414	
415	    @Override
416	    public String toString() {
417	        return new ToStringCreator(this)
418	
419	            .append("id", this.getId())
420	            .append("new", this.isNew())
421	            .append("lastName", this.getLastName())
422	            .append("firstName", this.getFirstName())
423	            .append("address", this.address)
424	            .append("city", this.city)
425	            .append("telephone", this.telephone)
426	            .toString();
427	    }
428	}
